 88	  async addMembers(sectionId, userIds, context) {
 89	    if (!Array.isArray(userIds) || userIds.length === 0) throw new BadRequestError('user_ids 배열이 필요합니다');
 90	    const uniqueUserIds = [...new Set(userIds)];
 91	    const result = await withTransaction(async (client) => {
 92	      const section = await SectionDAO.findById(client, sectionId, true);
 93	      if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');
 94	      const actor = await BinderDAO.getMember(client, section.binder_id, context.sender_id);
 95	      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');
 96	      if (section.access_scope !== 1) throw new BadRequestError('public 섹션에는 멤버를 추가할 수 없습니다');
 97	      const added = [];
 98	      for (const userId of uniqueUserIds) {
 99	        const target = await BinderDAO.getMember(client, section.binder_id, userId);
100	        if (!target || target.deleted_at) throw new BadRequestError('모든 user_id는 활성 바인더 멤버여야 합니다');
101	        if (await SectionDAO.addMember(client, sectionId, userId, generateUUID())) added.push(userId);
102	      }
103	      return { binderId: section.binder_id, added_user_ids: added, member_count: await SectionDAO.countMembers(client, sectionId) };
104	    });
105	    eventBus.emit('sync', { binder_id: result.binderId, sender_id: context.sender_id, device_uuid: context.device_uuid,
106	      action: ActionType.UPDATE, target_type: TargetType.SECTION, target_id: sectionId });
107	    return { added_user_ids: result.added_user_ids, member_count: result.member_count };
108	  }
